// src/env.ts
function readCloudConnectorEnv(env = process.env) {
  const supabaseUrl = env.SUPABASE_URL ?? env.VITE_SUPABASE_URL;
  const supabaseAnonKey = env.SUPABASE_ANON_KEY ?? env.VITE_SUPABASE_ANON_KEY;
  const supabaseJwtSecret = env.SUPABASE_JWT_SECRET;
  const webOrigin = env.PATHRULE_WEB_ORIGIN ?? "https://app.pathrule.io";
  const tokenEncryptionKey = env.PATHRULE_CONNECTOR_TOKEN_ENCRYPTION_KEY;
  const tokenEncryptionKeyVersion = Number(
    env.PATHRULE_CONNECTOR_TOKEN_ENCRYPTION_KEY_VERSION ?? "1"
  );
  if (!supabaseUrl) {
    throw new Error("SUPABASE_URL is required for Pathrule Remote MCP.");
  }
  if (!supabaseAnonKey) {
    throw new Error("SUPABASE_ANON_KEY is required for Pathrule Remote MCP.");
  }
  if (!supabaseJwtSecret) {
    throw new Error("SUPABASE_JWT_SECRET is required for Pathrule Remote MCP.");
  }
  return {
    supabaseUrl,
    supabaseAnonKey,
    supabaseJwtSecret,
    webOrigin,
    tokenEncryptionKey,
    tokenEncryptionKeyVersion
  };
}

// src/db/supabase.ts
var cachedClient = null;
function getConnectorSupabase() {
  if (cachedClient) return cachedClient;
  const env = readCloudConnectorEnv();
  cachedClient = createClient(env.supabaseUrl, env.supabaseAnonKey, {
    // A serverless invocation is killed by the platform eventually, but "eventually" is not a
    // deadline: the request that hangs consumes the whole invocation and the MCP client on the
    // other end gets a timeout with no cause attached.
    global: { fetch: createTimeoutFetch(fetch) },
    auth: {
      persistSession: false,
      autoRefreshToken: false
    }
  });
  return cachedClient;
}
function createUserScopedSupabase(accessToken) {
  const env = readCloudConnectorEnv();
  return createClient(env.supabaseUrl, env.supabaseAnonKey, {
    auth: {
      persistSession: false,
      autoRefreshToken: false
    },
    global: {
      headers: {
        Authorization: `Bearer ${accessToken}`
      },
      fetch: createTimeoutFetch(fetch)
    }
  });
}

